def load_all_grids():
    """Load all grid data from current session."""
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        return {}

    # Find the sessions file - it's in the parent of the RLm_SESSION_DIR folder
    base_dir = os.path.dirname(d)
    sessions_file = os.path.join(base_dir, '..', 'sessions', os.path.basename(d) + '.jsonl')

    # Try different possible locations
    possible_files = [
        os.path.normpath(os.path.join(os.getcwd(), '../../sessions/' + os.path.basename(d) + '.jsonl')),
        os.path.join(d, '..', '..', 'sessions', os.path.basename(d) + '.jsonl'),
        d.replace('.jsonl', ''),  # might be nested
    ]

    t = ""
    for sf in possible_files:
        try:
            if os.path.exists(sf):
                with open(sf, 'r') as f:
                    t = f.read()
                break
        except:
            continue

    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        content_start = m.end()
        rows_raw = t[content_start:].split('\n')[:h]
        rows_clean = []
